+	struct devlink_param_u64_array new_arr = {};
+	char *copy, *token, *saveptr = NULL;
+	uint64_t val, *new_val;
+	char delim[] = " ,";
+	int err, i;
+
+	copy = strdup(param_value);
+	if (!copy)
